/* eslint-disable no-undef */

/**
 * The HRMS service worker (document 11).
 *
 * Written by hand rather than generated by Workbox. For a scope this small —
 * one app shell and one offline queue — Workbox adds a layer of abstraction
 * that has to be understood before anyone can debug why a request did not enter
 * the cache.
 *
 * THE RULES BINDING THIS FILE
 *
 * 1. Sensitive data NEVER enters Cache Storage. Payslips, dashboards, the
 *    employee list, and confidential cases may only exist in page memory
 *    (document 11 §5.4). Cache Storage survives a logout and can be read by any
 *    script on the same origin.
 *
 * 2. Tokens NEVER touch the cache. The access token lives in page memory; the
 *    refresh token is an httpOnly cookie that is not even visible from here.
 *
 * 3. The only offline write is a PUNCH, because that is the only thing genuinely
 *    blocked by the network (P16). A leave request can wait; a person standing
 *    at the factory gate at seven in the morning cannot.
 */

const VERSION = 'v1';
const SHELL_CACHE = `hrms-shell-${VERSION}`;

/**
 * The application shell only. Not one data endpoint is here.
 */
const SHELL_ASSETS = ['/', '/attendance/punch', '/manifest.webmanifest', '/icon-192.svg'];

/** Paths that must not enter the cache under any circumstances. */
const NEVER_CACHE = [
  '/api/',
  '/admin/',
  '/login',
  '/reset-password',
  '/accept-invitation',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // `addAll` fails entirely when one file fails. Handled per file so that one
      // missing asset does not stop the service worker installing at all.
      // dipasang sama sekali.
      .then((cache) => Promise.allSettled(SHELL_ASSETS.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== SHELL_CACHE).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Two guards, and both are needed. The first closes the paths already known;
  // the second closes the ones that do not exist yet — a data page added in a
  // later phase will not be cached automatically merely because nobody
  // remembered to update this list.
  if (NEVER_CACHE.some((prefix) => url.pathname.startsWith(prefix))) return;
  if (request.headers.get('authorization')) return;

  // Network-first for navigation: an HR application showing yesterday's data is
  // more dangerous than one that refuses to open.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() =>
        caches.match(request).then((cached) => cached ?? caches.match('/attendance/punch')),
      ),
    );
    return;
  }

  // Cache-first only for static assets, which are versioned by their file names.
  if (url.pathname.startsWith('/_next/static/') || url.pathname.endsWith('.svg')) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            const copy = response.clone();
            void caches.open(SHELL_CACHE).then((cache) => cache.put(request, copy));
            return response;
          }),
      ),
    );
  }
});

/**
 * The full wipe on logout.
 *
 * Triggered by the page through postMessage. This is what stops user A's data
 * being read by user B on a shared device — the ordinary case in an HR room and
 * at a security post (risk R50).
 */
self.addEventListener('message', (event) => {
  if (event.data?.type === 'HRMS_LOGOUT') {
    event.waitUntil(
      caches.keys().then((keys) => Promise.all(keys.map((key) => caches.delete(key)))),
    );
  }
});

/**
 * Web Push (document 11 §7).
 *
 * `userVisibleOnly: true` is required by the browser and deliberately not fought:
 * a silent push is the ability to track a device's presence without its owner
 * knowing, and no HRIS need justifies it.
 *
 * Its payload is already encrypted for this device — the push service in between
 * cannot read it. Even so its contents are kept thin: a title, one line, and a
 * link. **No salary figures, no national ID, no leave reason.** A notification
 * appears on a lock screen anyone standing near the device can see, and
 * encryption does not help there.
 */
self.addEventListener('push', (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    // An unparseable payload is ignored silently. Showing a notification holding
    // raw text would put fragments of JSON on the user's lock screen.
    // di layar terkuncinya.
    return;
  }

  const title = payload.title;
  if (typeof title !== 'string' || title.length === 0) return;

  event.waitUntil(
    self.registration.showNotification(title, {
      body: typeof payload.body === 'string' ? payload.body : '',
      icon: '/icon.svg',
      // Notifications with the same tag replace each other. Three leave requests
      // decided one after another produce three notifications; three delivery
      // attempts for the SAME decision must produce one.
      tag: typeof payload.tag === 'string' ? payload.tag : 'hrms',
      renotify: false,
      data: { url: typeof payload.url === 'string' ? payload.url : '/' },
    }),
  );
});

/**
 * A notification click.
 *
 * An already-open tab is FOCUSED rather than replaced by a new one. Opening a
 * second tab on an application that is already running leaves two sessions on
 * the same device — and on a shared device, a forgotten tab is a session left
 * open.
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = event.notification.data?.url ?? '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          void client.navigate?.(target);
          return client.focus();
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});
